// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {L1Block} from "../src/L1Block.sol";

contract InvMutTest is Test {
    L1Block c;

    function setUp() public { c = new L1Block(); }

    function testFuzz_property(
        uint64 number0,
        uint64 timestamp0,
        uint256 basefee0,
        bytes32 hash0,
        uint64 seq0,
        bytes32 batcher0,
        uint256 overhead0,
        uint256 scalar0,
        uint64 number1,
        uint64 timestamp1,
        uint256 basefee1,
        bytes32 hash1,
        uint64 seq1,
        bytes32 batcher1,
        uint256 overhead1,
        uint256 scalar1
    ) public {
        address depositor = 0xDeaDDEaDDeAdDeAdDEAdDEaddeAddEAdDEAd0001;

        vm.prank(depositor);
        c.setL1BlockValues(number0, timestamp0, basefee0, hash0, seq0, batcher0, overhead0, scalar0);

        vm.prank(depositor);
        c.setL1BlockValues(number1, timestamp1, basefee1, hash1, seq1, batcher1, overhead1, scalar1);

        assertEq(uint256(c.timestamp()), uint256(timestamp1));
    }
}
